import{_ as a,a0 as s,w as i,s as p,I as e,x as t,a1 as o,A as r,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"Cloudflare 有了一个新东西，它可以替代互联网上烦人的验证码 | LCTT x X-CMD","titleTemplate":false,"description":"Cloudflare 有了一个新东西，它可以替代互联网上烦人的验证码 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Cloudflare 有了一个新东西，它可以替代互联网上烦人的验证码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Cloudflare 有了一个新东西，它可以替代互联网上烦人的验证码 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220609 Cloudflare Has Something New to Replace Annoying CAPTCHAs on the Internet","title":"Cloudflare 有了一个新东西，它可以替代互联网上烦人的验证码","tag":"202206","desc":""},"relativePath":"202206/20220609 Cloudflare Has Something New to Replace Annoying CAPTCHAs on the Internet.md","filePath":"[post].md"}'),d={name:"202206/20220609 Cloudflare Has Something New to Replace Annoying CAPTCHAs on the Internet.md"};function f(C,l,m,T,x,g){const n=s("Link");return i(),p("div",null,[l[23]||(l[23]=e("h1",{id:"cloudflare-有了一个新东西-它可以替代互联网上烦人的验证码",tabindex:"-1"},[t("Cloudflare 有了一个新东西，它可以替代互联网上烦人的验证码 "),e("a",{class:"header-anchor",href:"#cloudflare-有了一个新东西-它可以替代互联网上烦人的验证码","aria-label":"Permalink to “Cloudflare 有了一个新东西，它可以替代互联网上烦人的验证码”"},"​")],-1)),l[24]||(l[24]=e("p",null,[t("不想通过正确输入 "),e("ruby",null,[t("验证码"),e("rt",null,"CAPTCHA")]),t(" 来证明自己是个人类吗？Cloudflare 可能有了一个解决方案。")],-1)),l[25]||(l[25]=e("p",null,[e("img",{src:"https://news.itsfoss.com/wp-content/uploads/2022/06/cloudflare-private-access-tokens.jpg",alt:"Cloudflare"})],-1)),e("p",null,[l[1]||(l[1]=t("互联网服务巨头 Cloudflare 前两天 ",-1)),o(n,{href:"https://blog.cloudflare.com/eliminating-captchas-on-iphones-and-macs-using-new-standard/"},{default:r(()=>[...l[0]||(l[0]=[t("宣布了",-1)])]),_:1}),l[2]||(l[2]=t()),l[3]||(l[3]=e("ruby",null,[t("私有访问令牌"),e("rt",null,"Private Access Tokens")],-1)),l[4]||(l[4]=t(" 功能。这项功能旨在减少你在网络上看到的验证码数量，同时改善你的隐私。",-1))]),l[26]||(l[26]=u('<p>你可能已经发现，验证码在移动设备上是一种可怕的体验。通常，它们会最终会占据整个屏幕，有时甚至无法完成。</p><p>作为替代方案，网站可以选择收集唯一识别数据，以证明你是人类。当然，从隐私的角度来看，这种做法是很糟糕的。如果这么做，许多重视隐私的公司都几乎无法避免他们受到 <ruby>僵尸攻击<rt>bot attacks</rt></ruby>。</p><p>幸运的是，私有访问令牌（PAT）的发布将改变这一点。</p><h3 id="私有访问令牌会产生什么影响" tabindex="-1">私有访问令牌会产生什么影响？ <a class="header-anchor" href="#私有访问令牌会产生什么影响" aria-label="Permalink to “私有访问令牌会产生什么影响？”">​</a></h3><p>简而言之，私有访问令牌能够做到下面这些事：</p><ul><li>在支持的设备上减少验证码数量</li><li>增强用户隐私</li><li>允许网站所有者确保访问者来自真实设备</li></ul><p>然而，深入观察，我们可以看到私有访问令牌的影响力远不止于此。若使用传统的验证码，就有多个实体可以访问你的数据。</p><p>首先，你正在访问的网站知道你的 IP 地址和你正在访问的 URL。当然，这些数据是建立连接所需的最低要求。此外，对于更高级的功能，网站还会发送一些用户代理（UA）数据，还好这些数据并不是唯一可识别的。</p><p>然而，另一方，也就是验证码提供者，却可以收集更多的数据。与你要访问的网站一样，它也知道你的 IP 地址、用户代理数据和你访问的 URL。不幸的是，除此之外，他们还会收集其他数据，例如你的设备信息和交互数据。如果把这些信息，与你之前完成验证码的时间联系起来，你就会惊讶的发现，他们可以建立一个非常详细的属于你的个人资料。</p><p>幸运的是，有了 Cloudflare 的私有访问令牌，你就可以完全绕过验证码，从而阻止验证码提供者收集此类数据。</p><h3 id="私有访问令牌是如何工作的" tabindex="-1">私有访问令牌是如何工作的？ <a class="header-anchor" href="#私有访问令牌是如何工作的" aria-label="Permalink to “私有访问令牌是如何工作的？”">​</a></h3><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/06/PAT-Data-transfer-chart-1024x650.png" alt=""></p><p>验证码的理念是集中尽可能多的数据，私人访问令牌则恰恰相反，它将数据去中心化，因此任何一方都无法唯一识别你。在你提到数据共享之前，Cloudflare 就已经特别指出了，数据不会在各方之间共享。</p><p>当你访问使用 Cloudflare 和私人访问令牌的网站的时候，共有三方将处理你的数据的不同部分。</p><ol><li>网站。它只会知道你的 IP、URL 和用户代理，这也是建立连接所必需的。</li><li>你的设备制造商。他们只会知道那些用于验证设备是否真实所需的设备数据，而不会知道你正在访问哪个网站，或你的 IP 地址是什么。验证了你的设备后，他们将生成一个令牌，该令牌将发送到 Cloudflare。</li><li>Cloudflare。他们将收到这个令牌，令牌中不包含你的任何设备数据，只有制造商对它是正品的“保证”。他们知道的唯一其他数据，就是你正在访问的网站，同样，这是为你提供内容所必需的。</li></ol><p>通过这种方式，Cloudflare 无需接触你的数据，就可以对“你是一个人”充满信心。</p><h3 id="支持的操作系统-没有-linux" tabindex="-1">支持的操作系统：没有 Linux？ <a class="header-anchor" href="#支持的操作系统-没有-linux" aria-label="Permalink to “支持的操作系统：没有 Linux？”">​</a></h3><p>你可能已经意识到，私人访问令牌需要特定的操作系统功能才能工作。目前，它们仅存在于苹果最新的操作系统上，即 iOS 和 iPadOS 16，以及 macOS Ventura。这是因为苹果的操作系统只在有限的硬件上运行，设备验证会更加容易。</p><p>另一方面，Linux 是一种通用操作系统，旨在在各种硬件上运行。因此，我认为，在可预见的未来，它都不会支持私人访问令牌。</p><p>回到苹果，我想到私人访问令牌也可能导致消费者维修设备的权利出现一些问题。例如，如果我用第三方的非正品电池更换了老旧的 iPhone 原装电池，私人访问令牌系统会特殊对待这种情况吗？</p><p>如果是 Linux 手机呢？这些制造商，如 Pine64 和 Purism，可能没有支持这样一个系统的基础设施。是否可以在这些上使用私人访问令牌呢？</p>',21)),e("p",null,[l[6]||(l[6]=t("Cloudflare 在 ",-1)),o(n,{href:"https://blog.cloudflare.com/eliminating-captchas-on-iphones-and-macs-using-new-standard/"},{default:r(()=>[...l[5]||(l[5]=[t("公告",-1)])]),_:1}),l[7]||(l[7]=t(" 中提到：",-1))]),l[27]||(l[27]=e("blockquote",null,[e("p",null,"我们正在积极努力让其他客户和设备制造商也使用私人访问令牌框架。每当新客户开始使用它时，从该客户进入你网站的流量将自动开始要求令牌，你的访问者将自动看到更少的验证码。")],-1)),l[28]||(l[28]=e("p",null,"因此，我们希望看到它被更多的设备和操作系统采用。你如何看待 Cloudflare 的私人访问令牌呢？在下面的评论中发表你的看法吧！",-1)),l[29]||(l[29]=e("hr",null,null,-1)),e("p",null,[l[9]||(l[9]=t("via: ",-1)),o(n,{href:"https://news.itsfoss.com/cloudflare-pat/"},{default:r(()=>[...l[8]||(l[8]=[t("https://news.itsfoss.com/cloudflare-pat/",-1)])]),_:1})]),e("p",null,[l[14]||(l[14]=t("作者：",-1)),o(n,{href:"https://news.itsfoss.com/author/jacob/"},{default:r(()=>[...l[10]||(l[10]=[t("Jacob Crume",-1)])]),_:1}),l[15]||(l[15]=t(" 选题：",-1)),o(n,{href:"https://github.com/lkxed"},{default:r(()=>[...l[11]||(l[11]=[t("lkxed",-1)])]),_:1}),l[16]||(l[16]=t(" 译者：",-1)),o(n,{href:"https://github.com/lkxed"},{default:r(()=>[...l[12]||(l[12]=[t("lkxed",-1)])]),_:1}),l[17]||(l[17]=t(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:r(()=>[...l[13]||(l[13]=[t("wxy",-1)])]),_:1})]),e("p",null,[l[20]||(l[20]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...l[18]||(l[18]=[t("LCTT",-1)])]),_:1}),l[21]||(l[21]=t(" 原创编译，",-1)),o(n,{href:"https://linux.cn/"},{default:r(()=>[...l[19]||(l[19]=[t("Linux中国",-1)])]),_:1}),l[22]||(l[22]=t(" 荣誉推出",-1))])])}const w=a(d,[["render",f]]);export{A as __pageData,w as default};
